create table `person`
(
    id                           bigint auto_increment
        primary key,
    first_name                   varchar(50)                                                                                                                                                                                              not null,
    mi                           varchar(10)                                                                                                                                 default ''                                                   not null,
    last_name                    varchar(50)                                                                                                                                                                                              not null,
    callsign                     varchar(64)                                                                                                                                                                                              not null,
    street1                      varchar(128)                                                                                                                                default ''                                                   not null,
    street2                      varchar(128)                                                                                                                                default ''                                                   not null,
    apt                          varchar(10)                                                                                                                                 default ''                                                   not null,
    city                         varchar(50)                                                                                                                                 default ''                                                   not null,
    state                        varchar(128)                                                                                                                                default ''                                                   not null,
    zip                          varchar(10)                                                                                                                                 default ''                                                   not null,
    country                      varchar(25)                                                                                                                                 default ''                                                   not null,
    home_phone                   varchar(25)                                                                                                                                 default ''                                                   not null,
    alt_phone                    varchar(25)                                                                                                                                 default ''                                                   not null,
    email                        varchar(255)                                                                                                                                                                                             null,
    camp_location                varchar(200)                                                                                                                                default ''                                                   not null,
    on_site                      tinyint(1)                                                                                                                                  default 0                                                    not null,
    vehicle_blacklisted          tinyint(1)                                                                                                                                  default 0                                                    not null,
    date_verified                date                                                                                                                                                                                                     null,
    password                     varchar(255)                                                                                                                                                                                             not null,
    created_at                   datetime                                                                                                                                    default current_timestamp()                                  null,
    callsign_approved            tinyint(1)                                                                                                                                  default 0                                                    not null,
    shirt_size                   varchar(10)                                                                                                                                                                                              null,
    status                       enum ('active', 'alpha', 'auditor', 'bonked', 'echelon', 'deceased', 'dismissed', 'inactive', 'inactive extension', 'past prospective', 'prospective', 'resigned', 'retired', 'suspended', 'uberbonked') not null,
    status_date                  date                                                                                                                                                                                                     null,
    updated_at                   datetime                                                                                                                                    default current_timestamp()                                  not null comment 'Most recent modification time.',
    shirt_style                  varchar(32)                                                                                                                                                                                              null,
    gender_custom                varchar(32)                                                                                                                                                                                              null,
    bpguid                       varchar(64)                                                                                                                                                                                              null,
    sfuid                        varchar(64)                                                                                                                                                                                              null,
    emergency_contact            mediumtext                                                                                                                                                                                               null,
    vintage                      tinyint(1)                                                                                                                                  default 0                                                    not null,
    callsign_normalized          varchar(128)                                                                                                                                                                                             not null,
    callsign_soundex             varchar(128)                                                                                                                                                                                             not null,
    behavioral_agreement         tinyint(1)                                                                                                                                  default 0                                                    not null,
    callsign_pronounce           varchar(200)                                                                                                                                                                                             null,
    logged_in_at                 timestamp                                                                                                                                                                                                null,
    last_seen_at                 timestamp                                                                                                                                                                                                null,
    person_photo_id              bigint                                                                                                                                                                                                   null,
    known_rangers                text                                                                                                                                                                                                     null,
    known_pnvs                   text                                                                                                                                                                                                     null,
    lms_id                       varchar(191)                                                                                                                                                                                             null,
    reviewed_pi_at               datetime                                                                                                                                                                                                 null,
    pronouns                     enum ('', 'female', 'male', 'neutral', 'custom')                                                                                            default ''                                                   not null,
    pronouns_custom              varchar(191)                                                                                                                                                                                             not null,
    pi_reviewed_for_dashboard_at datetime                                                                                                                                                                                                 null,
    lms_username                 varchar(191)                                                                                                                                                                                             null,
    tshirt_swag_id               bigint unsigned                                                                                                                                                                                          null,
    tshirt_secondary_swag_id     bigint unsigned                                                                                                                                                                                          null,
    long_sleeve_swag_id          bigint unsigned                                                                                                                                                                                          null,
    vanity_changed_at            datetime                                                                                                                                                                                                 null,
    used_vanity_change           tinyint(1)                                                                                                                                  default 0                                                    not null,
    employee_id                  varchar(255)                                                                                                                                                                                             null,
    gender_identity              enum ('cis-female', 'cis-male', 'custom', 'female', 'fluid', 'male', '', 'non-binary', 'queer', 'trans-female', 'trans-male', 'two-spirit') default ''                                                   not null,
    preferred_name               varchar(255)                                                                                                                                default ''                                                   not null,
    years_seen                   longtext collate utf8mb4_bin                                                                                                                                                                             null
        check (json_valid(`years_seen`)),
    years_as_contributor         longtext collate utf8mb4_bin                                                                                                                                                                             null
        check (json_valid(`years_as_contributor`)),
    years_as_ranger              longtext collate utf8mb4_bin                                                                                                                                                                             null
        check (json_valid(`years_as_ranger`)),
    years_combined               longtext collate utf8mb4_bin                                                                                                                                                                             null
        check (json_valid(`years_combined`)),
    years_of_service             text                                                                                                                                        default '[]'                                                 not null,
    years_of_awards              text                                                                                                                                        default '[]'                                                 not null,
    years_of_signups             text                                                                                                                                        default '[]'                                                 not null,
    sms_number                   varchar(255)                                                                                                                                                                                             null,
    sms_stopped                  tinyint(1)                                                                                                                                  default 0                                                    not null,
    sms_code                     varchar(255)                                                                                                                                                                                             null,
    sms_verified                 tinyint(1)                                                                                                                                  default 0                                                    not null,
    on_boarded_at                datetime(6)                                                                                                                                                                                              null
)
collate = utf8mb4_unicode_ci;

create table timesheet
(
    id                        bigint unsigned auto_increment
        primary key,
    position_id               bigint unsigned                                                                         not null,
    person_id                 bigint                                                                                  not null,
    on_duty                   datetime                                                                                not null comment 'date/time that person signed onto duty',
    off_duty                  datetime                                                                                null comment 'date/time that person signed off of duty',
    verified_at               datetime                                                                                null,
    verified_person_id        bigint                                                                                  null,
    review_status             enum ('approved', 'rejected', 'pending', 'unverified', 'verified') default 'unverified' null,
    reviewer_person_id        bigint                                                                                  null,
    reviewed_at               datetime                                                                                null,
    slot_id                   bigint unsigned                                                                         null,
    is_echelon                tinyint(1)                                                         default 0            not null,
    suppress_duration_warning tinyint(1)                                                         default 0            not null,
    was_signin_forced         tinyint(1)                                                         default 0            not null,
    desired_position_id       bigint unsigned                                                                         null,
    desired_on_duty           datetime                                                                                null,
    desired_off_duty          datetime                                                                                null,
    signin_force_reason       text                                                                                    null
)
collate = utf8mb3_unicode_ci;

CREATE TABLE `position` (
    `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
    `title` varchar(40) NOT NULL,
    `new_user_eligible` tinyint(1) NOT NULL DEFAULT 0,
    `all_rangers` tinyint(1) NOT NULL DEFAULT 0,
    `count_hours` tinyint(1) NOT NULL DEFAULT 1,
    `min` int(10) NOT NULL DEFAULT 1 COMMENT 'Min suggested Rangers per slot',
    `max` int(10) DEFAULT NULL COMMENT 'Max suggested Rangers per slot',
    `on_sl_report` tinyint(1) DEFAULT NULL,
    `on_trainer_report` tinyint(1) NOT NULL DEFAULT 0,
    `short_title` varchar(6) DEFAULT NULL,
    `type` varchar(32) DEFAULT NULL,
    `training_position_id` bigint(20) unsigned DEFAULT NULL,
    `contact_email` varchar(200) DEFAULT NULL,
    `prevent_multiple_enrollments` tinyint(1) NOT NULL DEFAULT 0,
    `active` tinyint(1) NOT NULL DEFAULT 1,
    `alert_when_empty` tinyint(1) NOT NULL DEFAULT 0,
    `team_id` int(11) DEFAULT NULL,
    `require_training_for_roles` tinyint(1) NOT NULL DEFAULT 0,
    `team_category` enum('public','all_members','optional') NOT NULL DEFAULT 'public',
    `alert_when_becomes_empty` tinyint(1) NOT NULL DEFAULT 0,
    `alert_when_no_trainers` tinyint(1) NOT NULL DEFAULT 0,
    `paycode` varchar(255) DEFAULT NULL,
    `resource_tag` varchar(255) DEFAULT NULL,
    `deselect_on_team_join` tinyint(1) NOT NULL DEFAULT 0,
    `no_payroll_hours_adjustment` tinyint(1) NOT NULL DEFAULT 0,
    `no_training_required` tinyint(1) NOT NULL DEFAULT 0,
    `auto_sign_out` tinyint(1) NOT NULL DEFAULT 0,
    `sign_out_hour_cap` double(8,2) NOT NULL DEFAULT 0.00,
    `mvr_eligible` tinyint(1) NOT NULL DEFAULT 0,
    `pvr_eligible` tinyint(1) NOT NULL DEFAULT 0,
    `parent_position_id` int(11) DEFAULT NULL,
    `not_timesheet_eligible` tinyint(1) NOT NULL DEFAULT 0,
    `cruise_direction` tinyint(1) NOT NULL DEFAULT 0,
    `mvr_signup_eligible` tinyint(1) NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`),
    KEY `position_mvr_eligible_index` (`mvr_eligible`),
    KEY `position_pvr_eligible_index` (`pvr_eligible`),
    KEY `position_parent_position_id_index` (`parent_position_id`),
    KEY `position_cruise_direction_index` (`cruise_direction`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;

CREATE TABLE `person_position` (
    `person_id` bigint(20) unsigned NOT NULL,
    `position_id` bigint(20) unsigned NOT NULL,
    PRIMARY KEY (`person_id`,`position_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci COMMENT='links person to position';

CREATE TABLE `team` (
    `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
    `title` varchar(255) NOT NULL,
    `type` varchar(255) NOT NULL DEFAULT 'team',
    `active` tinyint(1) NOT NULL DEFAULT 1,
    `created_at` timestamp NULL DEFAULT NULL,
    `updated_at` timestamp NULL DEFAULT NULL,
    `mvr_eligible` tinyint(1) NOT NULL DEFAULT 0,
    `pvr_eligible` tinyint(1) NOT NULL DEFAULT 0,
    `email` varchar(255) DEFAULT NULL,
    `description` varchar(255) DEFAULT NULL,
    PRIMARY KEY (`id`),
    KEY `team_mvr_eligible_index` (`mvr_eligible`),
    KEY `team_pvr_eligible_index` (`pvr_eligible`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `person_team` (
   `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
   `person_id` int(11) NOT NULL,
   `team_id` int(11) NOT NULL,
   `created_at` timestamp NULL DEFAULT NULL,
   `updated_at` timestamp NULL DEFAULT NULL,
   PRIMARY KEY (`id`),
   UNIQUE KEY `person_team_person_id_team_id_unique` (`person_id`,`team_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
